"""Native window activation without loading Qt or the translation engine."""

import ctypes
import os
from pathlib import Path


def _windows_api():
    if os.name != "nt":
        return None
    from ctypes import wintypes

    user = ctypes.WinDLL("user32", use_last_error=True)
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    user.ShowWindowAsync.argtypes = [wintypes.HWND, ctypes.c_int]
    user.ShowWindowAsync.restype = wintypes.BOOL
    user.IsIconic.argtypes = [wintypes.HWND]
    user.IsIconic.restype = wintypes.BOOL
    user.IsWindowVisible.argtypes = [wintypes.HWND]
    user.IsWindowVisible.restype = wintypes.BOOL
    user.SetForegroundWindow.argtypes = [wintypes.HWND]
    user.SetForegroundWindow.restype = wintypes.BOOL
    user.GetWindowTextLengthW.argtypes = [wintypes.HWND]
    user.GetWindowTextLengthW.restype = ctypes.c_int
    user.GetWindowTextW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
    user.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
    kernel.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    kernel.OpenProcess.restype = wintypes.HANDLE
    kernel.QueryFullProcessImageNameW.argtypes = [wintypes.HANDLE, wintypes.DWORD, wintypes.LPWSTR, ctypes.POINTER(wintypes.DWORD)]
    kernel.QueryFullProcessImageNameW.restype = wintypes.BOOL
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    return user, kernel


def _show_handle(user, handle):
    # SW_RESTORE for a minimized window; SW_SHOW preserves a maximized window.
    # Async avoids waiting indefinitely on another process's UI thread.
    user.ShowWindowAsync(handle, 9 if user.IsIconic(handle) else 5)
    user.SetForegroundWindow(handle)


def activate_existing_window(app_dir):
    """Restore this installation's existing window, including a hidden one."""
    api = _windows_api()
    if api is None:
        return False
    from ctypes import wintypes

    user, kernel = api
    root = Path(app_dir).resolve()
    allowed = {os.path.normcase(str(root / "core" / "runtime" / "pythonw.exe")),
               os.path.normcase(str(root / "pdf2zh.exe")), os.path.normcase(str(root / "PaperRoute.exe"))}
    own_pid = os.getpid()
    found = []
    callback_type = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    @callback_type
    def visit(handle, unused):
        length = user.GetWindowTextLengthW(handle)
        if not length:
            return True
        title = ctypes.create_unicode_buffer(length + 1)
        user.GetWindowTextW(handle, title, len(title))
        if "PaperRoute" not in title.value:
            return True
        process_id = wintypes.DWORD()
        user.GetWindowThreadProcessId(handle, ctypes.byref(process_id))
        if process_id.value == own_pid:
            return True
        process = kernel.OpenProcess(0x1000, False, process_id.value)
        if not process:
            return True
        try:
            name = ctypes.create_unicode_buffer(32768)
            size = wintypes.DWORD(len(name))
            if kernel.QueryFullProcessImageNameW(process, 0, name, ctypes.byref(size)):
                if os.path.normcase(name.value) in allowed:
                    found.append(handle)
                    return False
        finally:
            kernel.CloseHandle(process)
        return True

    user.EnumWindows.argtypes = [callback_type, wintypes.LPARAM]
    user.EnumWindows.restype = wintypes.BOOL
    user.EnumWindows(visit, 0)
    if not found:
        return False
    _show_handle(user, found[0])
    return True


def show_main_window(window):
    """Show a Qt window and override a parent's Windows hidden-startup flag."""
    if window.isMinimized():
        window.showNormal()
    else:
        window.show()
    window.raise_()
    window.activateWindow()
    api = _windows_api()
    if api is not None:
        _show_handle(api[0], int(window.winId()))
